exec(open('tools/common.py').read())
# Bám sách: trang 90–91 + đáp án + Mini dictionary unit 43. Không chép nguyên văn.
theory = (
 H("A", "Talking about how you are", "Nói về tình trạng sức khỏe")
 + P("Two elderly people, Mrs Smith and Mr Jones, compare their health problems.", "Hai người lớn tuổi, bà Smith và ông Jones, kể cho nhau nghe chuyện sức khỏe.")
 + T([
    ("<b>throw off</b>", "(informal) Mrs Smith asks if Mr Jones has got rid of his cold.", "(thân mật) Bà Smith hỏi ông Jones đã khỏi cảm chưa."),
    ("<b>clear up</b> / <b>get over</b> / <b>pick up</b>", "The cold went away after a few days, but as soon as he felt better he caught another one.", "Cơn cảm khỏi sau vài ngày, nhưng ông vừa khỏe lại thì đã bị lây cơn khác."),
    ("<b>break out in</b> / <b>bunged-up</b>", "Sweat keeps suddenly appearing on his skin (also used of spots or a rash), and his nose is (informal) completely blocked.", "Ông cứ bỗng toát mồ hôi (cũng dùng cho mụn, mẩn ngứa), và mũi (thân mật) thì nghẹt hẳn."),
    ("<b>pass on</b> / <b>flare up</b>", "Mrs Smith hopes he won’t give the illness to her; her arthritis has come back again.", "Bà Smith mong ông không lây bệnh cho mình; bệnh viêm khớp của bà lại tái phát."),
    ("<b>heal up</b> / <b>go down</b>", "The cut on her hand is only now getting new skin, and the swelling has not yet returned to normal.", "Vết cắt trên tay bà giờ mới bắt đầu lên da non, và chỗ sưng vẫn chưa xẹp."),
 ])
 + H("B", "Feeling tired", "Cảm thấy mệt")
 + P("English has many phrasal verbs about sleep and tiredness. <b>Drop off</b> and <b>nod off</b> are both informal and mean fall asleep; <b>nod off</b> is used especially when you did not mean to sleep.", "Tiếng Anh có nhiều phrasal verb về giấc ngủ và sự mệt mỏi. <b>Drop off</b> và <b>nod off</b> đều thân mật, đều là ngủ thiếp đi; <b>nod off</b> dùng nhất là khi mình không định ngủ.")
 + T([
    ("<b>wear out</b> / <b>tire out</b> / <b>do in</b> (informal) / <b>wipe out</b> (informal)", "Make someone very tired, e.g. a whole day going round the shops. Adjectives: <b>worn out</b>, <b>tired out</b>, <b>done in</b> (informal), <b>wiped out</b> (informal).", "Làm ai rất mệt, ví dụ đi dạo cửa hàng cả ngày. Tính từ: <b>worn out</b>, <b>tired out</b>, <b>done in</b> (thân mật), <b>wiped out</b> (thân mật)."),
    ("<b>burn out</b>", "Become so ill or tired from overwork that you can no longer work creatively. Adjective <b>burnt-out</b>, noun <b>burnout</b>.", "Ốm hoặc mệt vì làm việc quá sức tới mức không thể làm việc sáng tạo được nữa. Tính từ <b>burnt-out</b>, danh từ <b>burnout</b>."),
    ("<b>washed out</b>", "(adjective) Looking tired, pale and ill, like Kay.", "(tính từ) Trông mệt, xanh xao và ốm, như Kay."),
 ], head=("Phrasal verb", "Meaning in the table", "Nghĩa trong bảng"))
 + H("C", "At the doctor’s", "Ở phòng khám")
 + P("A doctor talks to a patient who has caught a bug.", "Bác sĩ nói chuyện với một bệnh nhân bị nhiễm virus.")
 + T([
    ("<b>go around</b>", "Many people are complaining of this illness at the moment.", "Hiện có nhiều người mắc bệnh này."),
    ("<b>put</b> sb <b>on</b> / <b>knock out</b>", "The doctor gives the patient tablets which should make them sleep heavily (see Unit 20).", "Bác sĩ cho bệnh nhân dùng thuốc giúp ngủ say (xem bài 20)."),
    ("<b>come off</b>", "The patient must not stop taking them until the doctor says so.", "Bệnh nhân không được ngừng thuốc cho tới khi bác sĩ bảo."),
    ("<b>take</b> a lot <b>out of</b> / <b>build up</b>", "This bug makes you feel very weak, so when recovering you should eat lots of fruit and vegetables to make yourself stronger.", "Loại virus này làm người bệnh rất yếu, nên khi bắt đầu khỏe lại cần ăn nhiều rau quả để bồi bổ."),
 ])
)
